"use strict";

export const LEAPC_MANUAL_REF = "v1.2.0";

export const LEAPC_KEYWORD_ENTRIES = {
  "#define": {"kind": "directive", "library": null, "forms": ["#define NAME replacement, #define NAME"], "desc": "Makes NAME a macro: wherever it is used later in the program, the compiler puts the replacement text in its place. The replacement is the rest of the line; it may be empty. The commonest use is naming a constant.", "example": "#define W 4\n#define H (W - 1)\n#define AREA (W * H)\nint main(void)\n{\n    return AREA;\n}", "part": "03_keywords.md"},
  "#include": {"kind": "directive", "library": null, "forms": ["#include <leap.h>, #include \"leap.h\""], "desc": "Accepted, and does nothing. The library (printf, plot, malloc and the rest) is built into the ROM, so there is no header to include; the directive exists so that programs written for other C systems keep compiling.", "example": "#include <leap.h>\nint main(void)\n{\n    cls();\n    puts(\"no include needed\");\n    return 0;\n}", "part": "03_keywords.md"},
  "#pragma": {"kind": "directive", "library": null, "forms": ["#pragma hires"], "desc": "Keeps the compiled program out of the memory at $6000-$77FF, which the TS2068's high-resolution colour mode uses. A program that calls mode(1) should say so. The compiler fills that memory last, so only a large program reaches it; without the pragma, mode(1) in such a program stops it with run-time error 3, HI-RES IN USE.", "example": "#pragma hires\nint main(void)\n{\n    mode(1);\n    plot(0, 0);\n    mode(0);\n    return 0;\n}", "part": "03_keywords.md"},
  "#undef": {"kind": "directive", "library": null, "forms": ["#undef NAME"], "desc": "Removes the definition of the macro NAME, so that it may be defined again, with other text. If NAME is not defined, nothing happens.", "example": "#define N 4\n#undef N\n#define N 9\nint main(void) { return N; }", "part": "03_keywords.md"},
  "Arithmetic operators": {"kind": "operator", "library": null, "forms": ["+ - * / %"], "desc": "Addition, subtraction, multiplication, division and remainder. + and - also work as signs in front of one operand (-a, +a). * in front of one operand is something else: see Pointer and address operators.", "example": "int main(void)\n{\n    int a = 17, b = 5, z = 0, big = 32767;\n    unsigned u = 0;\n    cls();\n    printf(\"%d %d %d %d\\n\", a / b, a % b, -a / b, -a % b);\n    printf(\"%d %d\\n\", a / z, a % z);\n    printf(\"%d %u\\n\", big + 1, u - 1);", "part": "03_keywords.md"},
  "Assignment operators": {"kind": "operator", "library": null, "forms": ["lvalue = expression, lvalue += expression, and likewise -= *= /= %= &= |= ^= <<= >>="], "desc": "= stores the value of the expression in the object on its left, converting it to that object's type, and gives the value stored. Each of the others is shorthand: n += 4 means n = n + 4, except that n is worked out only once.", "example": "int main(void)\n{\n    int n = 10, m = 3, a, b;\n    n += 4;  n -= 2;  n *= 3;  n /= 5;  n %= 4;\n    m <<= 3;  m |= 5;  m ^= 9;  m &= 22;  m >>= 2;\n    a = b = 4;\n    cls();\n    printf(\"%d %d %d\\n\", n, m, a + b);", "part": "03_keywords.md"},
  "Bitwise operators": {"kind": "operator", "library": null, "forms": ["& | ^ ~ << >>"], "desc": "a & b, a | b and a ^ b work bit by bit: and, or, exclusive-or. ~a flips every bit. a << n shifts the bits of a left by n places, and a >> n right.", "example": "int main(void)\n{\n    int a = 12, b = 10, c = -16;\n    unsigned u = 0x8000;\n    cls();\n    printf(\"%d %d %d %d\\n\", a & b, a | b, a ^ b, ~a);\n    printf(\"%d %d %d %u\\n\", a << 2, a >> 2, c >> 2, u >> 15);\n    return 0;", "part": "03_keywords.md"},
  "Casts": {"kind": "operator", "library": null, "forms": ["( type ) expression"], "desc": "Converts the value of the expression to the type in the brackets. A cast between integer types keeps the low bits (to char, the low 8; from char the value is extended with zeros, from signed char with the sign) and so can lose information. A cast to a floating type is exact for any int or unsigned; a cast of a floating value to an integer type cuts off the fraction, toward zero.", "example": "int main(void)\n{\n    int i = 0x1234, n = 7;\n    cls();\n    printf(\"%d %d %u\\n\", (char)i, n / 2, (unsigned)-1);\n    printf(\"%.1f %d %d\\n\", (float)n / 2, (int)2.9, (int)-2.9);\n    return 0;\n}", "part": "03_keywords.md"},
  "Comma operator": {"kind": "operator", "library": null, "forms": ["expression , expression"], "desc": "Works out the left expression, throws its value away, then works out the right one, and gives its value. It has the lowest precedence of all, so it usually needs brackets.", "example": "int main(void)\n{\n    int n, a;\n    a = (n = 3, n + 1);\n    return a * 10 + n;\n}", "part": "03_keywords.md"},
  "Comparison operators": {"kind": "operator", "library": null, "forms": ["== != < > <= >="], "desc": "Compare two values. The answer is an int: 1 when the comparison holds, 0 when it does not.", "example": "int main(void)\n{\n    int a = -1;\n    unsigned u = 1;\n    cls();\n    printf(\"%d %d %d %d\\n\", a < 1, a < u, 3 == 3, 'a' != 97);\n    return 0;\n}", "part": "03_keywords.md"},
  "Conditional operator": {"kind": "operator", "library": null, "forms": ["test ? a : b"], "desc": "If test is not zero, the value is a; otherwise it is b. Only the one chosen is worked out. It groups from the right, so x ? 1 : y ? 2 : 3 is x ? 1 : (y ? 2 : 3).", "example": "int main(void)\n{\n    int a = 7, b = 3, k = 1;\n    cls();\n    printf(\"%d %d %.1f\\n\", a > b ? a : b, a == b ? 1 : a < b ? 2 : 3, k ? 1 : 0.5);\n    return 0;\n}", "part": "03_keywords.md"},
  "FREE": {"kind": "command", "library": null, "forms": ["FREE"], "desc": "Shows how much memory is left. It reports one row, white on black at the bottom of the screen, until you press a key:", "example": "", "part": "03_keywords.md"},
  "Increment and decrement": {"kind": "operator", "library": null, "forms": ["++ --"], "desc": "++x adds 1 to x and gives the new value; x++ adds 1 and gives the old value. --x and x-- take 1 away in the same way.", "example": "int a[3] = { 10, 20, 30 };\nint main(void)\n{\n    int i = 5, j, k;\n    int *p;\n    float f = 1.5;\n    j = i++;\n    k = ++i;", "part": "03_keywords.md"},
  "LIB": {"kind": "command", "library": null, "forms": ["LIB \"name\", LIB \"\", LIB"], "desc": "Loads a library of assembly-language functions from tape, or unloads the one that is loaded. LIB \"name\" loads the library with that name (1 to 10 characters); LIB \"\" loads the next library on the tape, whatever its name. LIB on its own unloads the library.", "example": "", "part": "03_keywords.md"},
  "LIST": {"kind": "command", "library": null, "forms": ["LIST"], "desc": "Shows the program a page (23 rows) at a time, with the keywords in bold. A line that does not fit on the page starts the next one. Press a key to see the next page; BREAK (CAPS SHIFT + SPACE) ends the listing.", "example": "", "part": "03_keywords.md"},
  "LOAD": {"kind": "command", "library": null, "forms": ["LOAD \"name\", LOAD \"\""], "desc": "Reads a program from tape and puts it in the editor, replacing the program that is there. LOAD \"name\" loads the program with that name; LOAD \"\" loads the next program on the tape, whatever it is called. While the tape plays, the status row shows LOADING and, once the header is found, LOADING name.", "example": "", "part": "03_keywords.md"},
  "Logical operators": {"kind": "operator", "library": null, "forms": ["&& || !"], "desc": "a && b is 1 if both are not zero, otherwise 0. a || b is 1 if either is not zero, otherwise 0. !a is 1 if a is zero, otherwise 0. The answer is always 0 or 1.", "example": "int n;\nint t(int v)\n{\n    n++;\n    return v;\n}\nint main(void)\n{", "part": "03_keywords.md"},
  "Member operators": {"kind": "operator", "library": null, "forms": ["structure . member, pointer -> member"], "desc": "Pick one member out of a structure. . is used with the structure itself, -> with a pointer to one: p->v means (*p).v. Members can be read, assigned to, and used with &.", "example": "struct node { int v; struct node *next; };\nstruct node a;\nstruct node b;\nint main(void)\n{\n    struct node *p;\n    a.v = 5;\n    b.v = 7;", "part": "03_keywords.md"},
  "NEW": {"kind": "command", "library": null, "forms": ["NEW"], "desc": "Clears the program, leaving the editor empty. Save the program first if you want to keep it.", "example": "", "part": "03_keywords.md"},
  "Pointer and address operators": {"kind": "operator", "library": null, "forms": ["&lvalue, pointer, pointer[index]"], "desc": "&x gives the address of x: a pointer to it. p is the object p points to (it can be read and assigned to). p[i] is (p + i). A pointer plus or minus an integer is moved by that many elements, not bytes. One pointer minus another of the same type gives the number of elements between them, as an int.", "example": "int a[4] = { 10, 20, 30, 40 };\nint main(void)\n{\n    int *p, *q;\n    int n = 5;\n    p = a;\n    q = &a[3];\n    cls();", "part": "03_keywords.md"},
  "RUN": {"kind": "command", "library": null, "forms": ["RUN"], "desc": "Compiles the whole program and, if there is no error, runs it. The status row shows COMPILING while it compiles. Nothing runs if the compiler finds a mistake. When the program ends, whatever is on the screen stays, and a report appears on the bottom row, white on black, until you press a key. The key is not typed; it returns you to the editor with the program as it was.", "example": "", "part": "03_keywords.md"},
  "SAVE": {"kind": "command", "library": null, "forms": ["SAVE \"name\""], "desc": "Writes the program (its source) to tape. name is 1 to 10 characters. While the tape moves, the status row shows SAVING name. Afterwards the report is shown on the bottom row until a key is pressed:", "example": "", "part": "03_keywords.md"},
  "VERIFY": {"kind": "command", "library": null, "forms": ["VERIFY \"name\", VERIFY \"\""], "desc": "Checks a tape against the program in the editor. Nothing is written and nothing in the program changes. VERIFY \"name\" looks for the program with that name; VERIFY \"\" takes the next program tape, whatever its name. The status row shows VERIFYING, then VERIFYING name when the header is found. The report is shown afterwards on the bottom row until a key is pressed:", "example": "", "part": "03_keywords.md"},
  "abs": {"kind": "function", "library": null, "forms": ["int abs(int n)"], "desc": "The size of n without its sign: n if it is 0 or more, -n if it is less.", "example": "int main(void)\n{\n    cls();\n    printf(\"%d %d %d\", abs(-5), abs(0), abs(-32768));\n    return abs(-9);\n}", "part": "04_library.md"},
  "at": {"kind": "function", "library": null, "forms": ["void at(int row, int col)"], "desc": "Moves the print position, so that the next text printed starts at that row and col. Row 0 is the top of the screen, column 0 the left edge. at prints nothing.", "example": "int main(void)\n{\n    cls();\n    at(2, 5);\n    print(\"HERE\");\n    at(5, 0);\n    print(\"AT\");\n    at(99, 0);", "part": "04_library.md"},
  "atoi": {"kind": "function", "library": null, "forms": ["int atoi(const char *s)"], "desc": "The whole number at the start of the string s: leading spaces and control characters are skipped, then an optional + or -, then decimal digits up to the first character that is not a digit.", "example": "int main(void)\n{\n    cls();\n    printf(\"%d %d %d\", atoi(\"123\"), atoi(\"  -45xyz\"), atoi(\"abc\"));\n    return atoi(\"+7\");\n}", "part": "04_library.md"},
  "attr": {"kind": "function", "library": null, "forms": ["int attr(int row, int col)"], "desc": "The attribute byte of the character cell at row (0 to 23) and col (0 to 31): the cell's colours as the screen holds them. The byte is flash  128 + bright  64 + paper * 8 + ink.", "example": "// attr: 1 3 114\nint main(void)\n{\n    cls();\n    ink(2);\n    paper(6);\n    bright(1);\n    at(1, 3);", "part": "04_library.md"},
  "auto": {"kind": "keyword", "library": null, "forms": ["auto declaration"], "desc": "A storage-class word for a local variable: auto int n;. It is accepted and ignored, because a variable declared in a function is automatic anyway.", "example": "int main(void)\n{\n    auto int n = 5;\n    return n;\n}", "part": "03_keywords.md"},
  "beep": {"kind": "function", "library": null, "forms": ["void beep(int frames, int semitone)"], "desc": "Plays a note on channel A of the AY sound chip. frames is how long it sounds, in display frames (the prototype's frames is unsigned; 0 plays nothing). semitone is the pitch counted from middle C: 0 is middle C, 12 is the C above it, -12 the C below. The program waits until the note ends.", "example": "// ay: 0=165 1=1 8=0\nint main(void)\n{\n    beep(8, 7);\n    beep(8, 4);\n    beep(8, 0);\n    return 0;\n}", "part": "04_library.md"},
  "border": {"kind": "function", "library": null, "forms": ["void border(int n)"], "desc": "Sets the colour of the border to n. The colours are 0 black, 1 blue, 2 red, 3 magenta, 4 green, 5 cyan, 6 yellow, 7 white.", "example": "int main(void)\n{\n    int c;\n    for (c = 0; c < 8; c++) {\n        border(c);\n        pause(10);\n    }\n    border(7);", "part": "04_library.md"},
  "box": {"kind": "library function", "library": "shapes", "forms": ["void box(int x0, int y0, int x1, int y1)"], "desc": "Draws the four sides of the rectangle with opposite corners x0, y0 and x1, y1, each point once, in the print attribute and in over mode like plot(). The corners may be given in either order. A coordinate that is off the screen is moved to its edge, as draw() does, so box(-5, -5, 300, 200) draws the edge of the screen.", "example": "// library: shapes\n// pixel: 60 40 1\n// pixel: 196 152 1\n// pixel: 60 100 1\n// pixel: 196 100 1\n// pixel: 128 40 1\n// pixel: 128 152 1\n// pixel: 128 100 0", "part": "06_libraries.md"},
  "break": {"kind": "keyword", "library": null, "forms": ["break;"], "desc": "Leaves the nearest enclosing for, while, do or switch at once. The program goes on with the statement after it.", "example": "int main(void)\n{\n    int i;\n    for (i = 0; i < 10; i++)\n        if (i == 4)\n            break;\n    return i;\n}", "part": "03_keywords.md"},
  "bright": {"kind": "function", "library": null, "forms": ["void bright(int n)"], "desc": "Switches bright on (n odd) or off (n even) for everything printed, plotted or drawn from now on, and for the cells cls() paints. bright(1) is the brighter set of the eight colours.", "example": "// attr: 0 0 0x78\n// attr: 0 1 0x38\nint main(void)\n{\n    cls();\n    bright(1);\n    print(\"B\");\n    bright(0);", "part": "04_library.md"},
  "case": {"kind": "keyword", "library": null, "forms": ["case constant :"], "desc": "A label inside a switch. When the value of the switch expression equals the constant, the program continues from the statement after the label. A constant may be a number, a character such as 'a', an enum name, or a constant expression. Labels do not stop the program: it runs on into the next one unless a break (or a return) intervenes.", "example": "int f(int v)\n{\n    int r = 0;\n    switch (v) {\n    case 1:   r = 10;\n    case 2:   r += 3; break;\n    case 'a': r = 7; break;\n    default:  r = 99;", "part": "03_keywords.md"},
  "char": {"kind": "keyword", "library": null, "forms": ["char"], "desc": "A type of one byte. char is unsigned: it holds 0 to 255, and char c = 255; stays 255. signed char holds -128 to 127 and is extended with its sign when it is used in an expression; unsigned char is the same as char. Character constants such as 'A' give the character's code.", "example": "int main(void)\n{\n    char c = 255;\n    signed char s = 255;\n    cls();\n    printf(\"%d %d %d\\n\", c, s, 'A');\n    c = c + 1;\n    printf(\"%d\\n\", c);", "part": "03_keywords.md"},
  "circle": {"kind": "library function", "library": "shapes", "forms": ["void circle(int x, int y, int r)"], "desc": "Draws the outline of a circle of radius r pixels, centred on the pixel x, y (the midpoint algorithm, all eight octants). It draws in the print attribute and in over mode like plot(), each point once. Points that fall off the screen are left out, so a circle can run off an edge. A negative radius is runtime error 4 (BAD ARGUMENT).", "example": "// library: shapes\n// pixel: 148 96 1\n// pixel: 108 96 1\n// pixel: 128 76 1\n// pixel: 128 116 1\n// pixel: 128 96 0\nint main(void)\n{", "part": "06_libraries.md"},
  "cls": {"kind": "function", "library": null, "forms": ["void cls(void)"], "desc": "Clears the whole screen to the current colours (paper and ink, bright and flash) and puts the print position at row 0, column 0.", "example": "// attr: 0 0 0x31\n// attr: 23 31 0x31\nint main(void)\n{\n    ink(1);\n    paper(6);\n    cls();\n    print(\"Hi\");", "part": "04_library.md"},
  "const": {"kind": "keyword", "library": null, "forms": ["const type name"], "desc": "Marks an object whose value is not to be changed: const int limit = 20;. Assigning to it afterwards, or adding to it with ++, is a compile error.", "example": "const int limit = 20;\nint main(void)\n{\n    return limit;\n}", "part": "03_keywords.md"},
  "continue": {"kind": "keyword", "library": null, "forms": ["continue;"], "desc": "Skips the rest of the body of the nearest enclosing loop and goes on with the next time round: in a for, to the step; in a while or do, to the test.", "example": "int main(void)\n{\n    int i, sum = 0;\n    for (i = 1; i <= 10; i++) {\n        if (i % 2 == 0)\n            continue;\n        sum += i;\n    }", "part": "03_keywords.md"},
  "default": {"kind": "keyword", "library": null, "forms": ["default:"], "desc": "The label in a switch that is taken when no case matches. It may stand anywhere among the cases, not only last. Without a default, a value that matches nothing skips the whole switch.", "example": "int main(void)\n{\n    int k = 7, r = 0;\n    switch (k) {\n    case 1: r = 1; break;\n    default: r = 2;\n    }\n    return r;", "part": "03_keywords.md"},
  "do": {"kind": "keyword", "library": null, "forms": ["do statement while ( expression );"], "desc": "Repeats the statement, then tests the expression, and goes round again while it is not zero. Because the test comes after the body, the body always runs at least once.", "example": "int main(void)\n{\n    int n = 3, sum = 0;\n    do {\n        sum += n;\n        n--;\n    } while (n > 0);\n    return sum;", "part": "03_keywords.md"},
  "double": {"kind": "keyword", "library": null, "forms": ["double"], "desc": "The same type as float: there is only one floating type in Leap-C, the 5-byte format of the TS2068's own ROM. double is accepted so that programs written for other compilers keep working, and sizeof(double) is 5.", "example": "int main(void)\n{\n    double d = 1.5;\n    return sizeof(double);\n}", "part": "03_keywords.md"},
  "draw": {"kind": "function", "library": null, "forms": ["void draw(int x0, int y0, int x1, int y1)"], "desc": "Draws a straight line from the pixel (x0, y0) to the pixel (x1, y1). Both end points are drawn. x counts from the left (0 to 255), y from the top (0 to 191). The line takes the current ink, paper, bright and flash in every character cell it touches, and obeys over.", "example": "// pixel: 10 20 1\n// pixel: 100 20 1\n// pixel: 9 20 0\n// pixel: 101 20 0\n// pixel: 0 0 1\n// pixel: 255 191 1\nint main(void)\n{", "part": "04_library.md"},
  "else": {"kind": "keyword", "library": null, "forms": ["if ( expression ) statement else statement"], "desc": "The part of an if statement that is done when the test is false. An else belongs to the nearest if that has none.", "example": "int t(int a, int b)\n{\n    int r;\n    r = 0;\n    if (a)\n        if (b) r = 1;\n        else r = 2;\n    return r;", "part": "03_keywords.md"},
  "enum": {"kind": "keyword", "library": null, "forms": ["enum tag { name [= constant] , ... }"], "desc": "Declares a set of named whole-number constants. The first name is 0, and each next one is one more than the one before, unless it is given a value with =, which restarts the count. A comma may follow the last name. The names are of type int; a variable of an enum type is an int too (2 bytes).", "example": "enum colour { RED, GREEN, BLUE = 10, CYAN };\nint main(void)\n{\n    enum colour c = CYAN;\n    return c + GREEN;\n}", "part": "03_keywords.md"},
  "exit": {"kind": "function", "library": null, "forms": ["void exit(int status)"], "desc": "Ends the program at once, from any depth of calls, with status as its result: exactly as if main had returned status. The shell then reports EXIT status.", "example": "void finish(int n)\n{\n    exit(n);\n}\nint main(void)\n{\n    cls();\n    print(\"start\");", "part": "04_library.md"},
  "extern": {"kind": "keyword", "library": null, "forms": ["extern declaration"], "desc": "Declares an object or function that is defined elsewhere, without making room for it. Use it to name a variable that a function needs before the variable is defined.", "example": "extern int total;\nint bump(void)\n{\n    total = total + 4;\n    return total;\n}\nint total = 5;\nint main(void)", "part": "03_keywords.md"},
  "flash": {"kind": "function", "library": null, "forms": ["void flash(int n)"], "desc": "Switches flashing on (n odd) or off (n even) for everything printed, plotted or drawn from now on, and for the cells cls() paints. A flashing cell alternates between its two colours.", "example": "// attr: 0 0 0xB8\n// attr: 0 1 0x38\nint main(void)\n{\n    cls();\n    flash(1);\n    print(\"F\");\n    flash(0);", "part": "04_library.md"},
  "float": {"kind": "keyword", "library": null, "forms": ["float"], "desc": "A number with a fraction. float and double are the same type: the 5-byte floating format of the TS2068 ROM, with about 9.6 significant digits and magnitudes up to about 1.7E38. It is not IEEE. Whole numbers convert to float exactly; a float converted to an integer loses its fraction, toward zero.", "example": "int main(void)\n{\n    float x = 2.5;\n    int n = x * 3;\n    cls();\n    printf(\"%.2f %d %d\\n\", x / 8, n, (int)-x);\n    return sizeof(float);\n}", "part": "03_keywords.md"},
  "for": {"kind": "keyword", "library": null, "forms": ["for ( start ; test ; step ) statement"], "desc": "A counting loop. start is done once. Then, before each time round, test is tried: if it is zero the loop ends. After each time round step is done. Any of the three parts may be left out; a missing test counts as true.", "example": "int main(void)\n{\n    int i, n;\n    cls();\n    for (i = 0, n = 1; i < 5; i++, n *= 2)\n        printf(\"%d \", n);\n    return n;\n}", "part": "03_keywords.md"},
  "frames": {"kind": "function", "library": null, "forms": ["unsigned frames(void)"], "desc": "The display frame counter: a number that goes up by one every frame (1/60 second on a TS2068, 1/50 on ZEsarUX), from 0 to 65535 and then round to 0 again.", "example": "unsigned t0, t1;\nint main(void)\n{\n    cls();\n    t0 = frames();\n    pause(10);\n    t1 = frames();\n    print(\"waited\");", "part": "04_library.md"},
  "free": {"kind": "function", "library": null, "forms": ["void free(void *p)"], "desc": "Gives back to the heap the block that malloc returned as p, so that a later malloc can use it again. free(0) (the null pointer, NULL) does nothing.", "example": "int main(void)\n{\n    char *p;\n    char *q;\n    p = malloc(20);\n    strcpy(p, \"heap\");\n    cls();\n    puts(p);", "part": "04_library.md"},
  "getkey": {"kind": "function", "library": null, "forms": ["int getkey(void)"], "desc": "Waits until a key is pressed and gives its code. Letters, digits and symbols give their ASCII codes ('a' is 97, 'A' is 65, '0' is 48); the other keys give the editor's control codes: 1 to 4 for the cursor keys, 8 for DELETE, 11 for CAPS SHIFT + ENTER, 13 for ENTER and 15 for CAPS SHIFT + 1 (the table is in [Appendix D](08_appendices.md#what-getkey-returns)).", "example": "int main(void)\n{\n    int k;\n    cls();\n    print(\"Y or N? \");\n    k = getkey();\n    putchar(k);\n    return k;", "part": "04_library.md"},
  "gets": {"kind": "function", "library": null, "forms": ["char gets(char buf, int max)"], "desc": "Reads a line typed at the keyboard into the buffer buf, which holds max characters, and returns buf. The characters are shown as you type them, starting at the print position. DELETE removes the last character typed. ENTER ends the line: the text is finished with a NUL, the print position moves to the start of the next row, and gets returns.", "example": "char buf[20];\nint main(void)\n{\n    cls();\n    print(\"Name? \");\n    gets(buf, 20);\n    printf(\"Hi %s\", buf);\n    return strlen(buf);", "part": "04_library.md"},
  "goto": {"kind": "keyword", "library": null, "forms": ["goto label ;"], "desc": "Continues the program at label, which is a name followed by a colon at the start of a statement, in the same function. It can jump forward or back, and out of loops and blocks.", "example": "int main(void)\n{\n    int n = 0;\nagain:\n    n++;\n    if (n < 5)\n        goto again;\n    return n;", "part": "03_keywords.md"},
  "if": {"kind": "keyword", "library": null, "forms": ["if ( expression ) statement, if ( expression ) statement else statement"], "desc": "Does the statement when the expression is not zero. With an else, does the second statement when it is zero. if statements can follow else to make a chain.", "example": "int sign(int n)\n{\n    if (n < 0)\n        return -1;\n    else if (n == 0)\n        return 0;\n    else\n        return 1;", "part": "03_keywords.md"},
  "ink": {"kind": "function", "library": null, "forms": ["void ink(int n)"], "desc": "Sets the ink colour for everything printed, plotted or drawn from now on, and for the cells cls() paints. The colours are 0 black, 1 blue, 2 red, 3 magenta, 4 green, 5 cyan, 6 yellow, 7 white.", "example": "// attr: 0 0 0x3A\n// attr: 0 1 0x39\nint main(void)\n{\n    cls();\n    ink(2);\n    print(\"R\");\n    ink(9);", "part": "04_library.md"},
  "inkey": {"kind": "function", "library": null, "forms": ["int inkey(void)"], "desc": "The code of the key pressed since the last call of getkey, inkey or gets, or 0 if none has been. It never waits. The codes are the same as for getkey.", "example": "int main(void)\n{\n    int n = 0, k;\n    cls();\n    while ((k = inkey()) == 0)\n        n++;\n    printf(\"%d\", n);\n    return k;", "part": "04_library.md"},
  "inp": {"kind": "function", "library": null, "forms": ["int inp(int port)"], "desc": "Reads the Z80 I/O port whose 16-bit address is port, and gives the byte read (0 to 255).", "example": "// ay: 0=77\nint main(void)\n{\n    cls();\n    outp(0xF5, 0);\n    outp(0xF6, 77);\n    outp(0xF5, 0);\n    printf(\"%d\", inp(0xF6));", "part": "04_library.md"},
  "int": {"kind": "keyword", "library": null, "forms": ["int"], "desc": "A whole number of 16 bits, from -32768 to 32767. It wraps around: 32767 + 1 is -32768. short, short int, signed and signed int are the same type; unsigned and unsigned int hold 0 to 65535. Where C allows the type to be left out, it is int: static count;, const limit = 5;, and a function defined as main().", "example": "int main(void)\n{\n    int big = 32767;\n    unsigned u = 65535;\n    cls();\n    printf(\"%d %d %u\\n\", big, big + 1, u);\n    return 0;\n}", "part": "03_keywords.md"},
  "inverse": {"kind": "function", "library": null, "forms": ["void inverse(int n)"], "desc": "Switches inverse on (n odd) or off (n even). While it is on, everything printed, plotted or drawn takes the cell's colours with ink and paper swapped.", "example": "// attr: 0 0 0x07\n// attr: 0 1 0x38\nint main(void)\n{\n    cls();\n    inverse(1);\n    print(\"I\");\n    inverse(0);", "part": "04_library.md"},
  "isqrt": {"kind": "library function", "library": "shapes", "forms": ["unsigned isqrt(unsigned n)"], "desc": "The integer square root of n: the largest whole number r with r x r not more than n. The result is 0 to 255 (the root of 65535 is 255). A negative int given as n is read as the unsigned number with the same bits.", "example": "// library: shapes\nint main(void)\n{\n    cls();\n    printf(\"%u %u %u\", isqrt(144), isqrt(168), isqrt(169));\n    return isqrt(150);\n}", "part": "06_libraries.md"},
  "itoa": {"kind": "function", "library": null, "forms": ["char itoa(int n, char buf, int base)"], "desc": "Writes the number n as text, in the number base base, into the buffer buf, finishes it with a NUL and returns buf. base may be 2 to 36; the digits above 9 are the lowercase letters a to z.", "example": "char s[20];\nint main(void)\n{\n    cls();\n    puts(itoa(255, s, 16));\n    puts(itoa(-255, s, 10));\n    puts(itoa(5, s, 2));\n    puts(itoa(-1, s, 16));", "part": "04_library.md"},
  "malloc": {"kind": "function", "library": null, "forms": ["void *malloc(unsigned n)"], "desc": "Takes a block of n bytes from the heap and returns a pointer to its first byte, or 0 (the null pointer, which a program may also write NULL) if no free block is large enough. The contents of the block are not cleared. Give the block back with free when you have finished with it.", "example": "int main(void)\n{\n    int *a;\n    int i, sum = 0;\n    cls();\n    a = malloc(10 * sizeof(int));\n    if (a == 0) {\n        print(\"no room\");", "part": "04_library.md"},
  "memcmp": {"kind": "function", "library": null, "forms": ["int memcmp(const void a, const void b, unsigned n)"], "desc": "Compares the first n bytes at a with the first n at b. The result is negative if the first byte that differs is smaller in a, positive if it is larger, and 0 if all n bytes are equal. The bytes are compared as unsigned numbers, 0 to 255; a NUL byte is compared like any other, so memcmp does not stop at the end of a string.", "example": "int main(void)\n{\n    cls();\n    printf(\"%d %d %d\", memcmp(\"abc\", \"abd\", 3) < 0,\n                       memcmp(\"abc\", \"abc\", 3),\n                       memcmp(\"abd\", \"abc\", 3) > 0);\n    return memcmp(\"abc\", \"xyz\", 0);\n}", "part": "04_library.md"},
  "memcpy": {"kind": "function", "library": null, "forms": ["void memcpy(void d, const void *s, unsigned n)"], "desc": "Copies n bytes from the memory at s to the memory at d, and returns d.", "example": "char src[8] = \"Leap-C\";\nchar dst[8];\nint main(void)\n{\n    cls();\n    memcpy(dst, src, 7);\n    puts(dst);\n    memcpy(dst + 1, \"xy\", 2);", "part": "04_library.md"},
  "memmove": {"kind": "function", "library": null, "forms": ["void memmove(void d, const void *s, unsigned n)"], "desc": "Copies n bytes from s to d, as memcpy does, and returns d. The blocks may overlap, in either direction: the bytes arrive as if they had first been copied to a separate place.", "example": "char s[8] = \"ABCDEF\";\nint main(void)\n{\n    cls();\n    memmove(s + 2, s, 4);\n    puts(s);\n    memmove(s, s + 2, 4);\n    puts(s);", "part": "04_library.md"},
  "memset": {"kind": "function", "library": null, "forms": ["void memset(void p, int c, unsigned n)"], "desc": "Sets n bytes starting at p to the value c, and returns p.", "example": "char s[8];\nint main(void)\n{\n    cls();\n    memset(s, '*', 5);\n    s[5] = 0;\n    puts(s);\n    memset(s, 'o', 2);", "part": "04_library.md"},
  "mode": {"kind": "function", "library": null, "forms": ["void mode(int n)"], "desc": "Chooses the display mode: mode(0) is the normal screen, mode(1) the TS2068's high-resolution colour mode, in which the colours are given for every 8 by 1 pixels instead of every 8 by 8 (see the concept [High resolution](05_concepts.md#high-resolution)). The end of a program always puts the machine back in mode 0.", "example": "#pragma hires\nint main(void)\n{\n    int n;\n    mode(1);\n    plot(10, 10);\n    n = point(10, 10);\n    mode(0);", "part": "04_library.md"},
  "outp": {"kind": "function", "library": null, "forms": ["void outp(int port, int value)"], "desc": "Writes the byte value (its low 8 bits) to the Z80 I/O port whose 16-bit address is port.", "example": "// ay: 2=100\nint main(void)\n{\n    outp(0xF5, 2);\n    outp(0xF6, 100);\n    return 0;\n}", "part": "04_library.md"},
  "over": {"kind": "function", "library": null, "forms": ["void over(int n)"], "desc": "Switches over mode on (n odd) or off (n even). In over mode, printing and plotting do not replace what is on the screen: they combine with it by exclusive-or. Printing a character twice in the same place therefore erases it, and so does plotting a pixel or drawing a line twice.", "example": "int main(void)\n{\n    cls();\n    print(\"ABC\");\n    over(1);\n    at(0, 1);\n    print(\"B\");\n    over(0);", "part": "04_library.md"},
  "paper": {"kind": "function", "library": null, "forms": ["void paper(int n)"], "desc": "Sets the paper colour (the background of a character cell) for everything printed, plotted or drawn from now on, and for the cells cls() paints. The colours are 0 black, 1 blue, 2 red, 3 magenta, 4 green, 5 cyan, 6 yellow, 7 white.", "example": "// attr: 0 0 0x17\n// attr: 12 12 0x17\nint main(void)\n{\n    paper(2);\n    ink(7);\n    cls();\n    print(\"P\");", "part": "04_library.md"},
  "pause": {"kind": "function", "library": null, "forms": ["void pause(unsigned n)"], "desc": "Waits for n display frames (1/60 second each on a TS2068, 1/50 on ZEsarUX) and then goes on. pause(0) returns at once.", "example": "int main(void)\n{\n    unsigned t0, t1;\n    cls();\n    t0 = frames();\n    pause(25);\n    t1 = frames();\n    print(\"done\");", "part": "04_library.md"},
  "plot": {"kind": "function", "library": null, "forms": ["void plot(int x, int y)"], "desc": "Sets the pixel at x (0 to 255, from the left) and y (0 to 191, from the top). The pixel is drawn in the current ink, and the character cell that holds it takes the current ink, paper, bright and flash.", "example": "// pixel: 0 0 1\n// pixel: 255 191 1\n// pixel: 100 50 1\n// pixel: 101 50 0\n// attr: 6 12 0x3A\nint main(void)\n{\n    cls();", "part": "04_library.md"},
  "point": {"kind": "function", "library": null, "forms": ["int point(int x, int y)"], "desc": "1 if the pixel at x (0 to 255) and y (0 to 191, from the top) is set, otherwise 0.", "example": "int main(void)\n{\n    cls();\n    plot(20, 30);\n    printf(\"%d %d %d\", point(20, 30), point(21, 30), point(-1, 30));\n    return point(20, 30);\n}", "part": "04_library.md"},
  "print": {"kind": "function", "library": null, "forms": ["void print(const char *s)"], "desc": "Prints the string s at the print position. It does not add a new line: the position is left just after the last character. A '\\n' inside the string starts a new row.", "example": "int main(void)\n{\n    cls();\n    print(\"one\");\n    print(\"two\");\n    print(\"\\nthree\");\n    return 0;\n}", "part": "04_library.md"},
  "printf": {"kind": "function", "library": null, "forms": ["int printf(const char *fmt, ...)"], "desc": "Prints the string fmt, replacing each conversion in it (a % and what follows) with the next of the arguments, in order. All other characters, '\\n' included, are printed as they are. printf is the one library function that takes any number of arguments, and the compiler does not check them against the format: the conversions and the arguments must agree.", "example": "int main(void)\n{\n    int n = 7;\n    cls();\n    printf(\"%d %d\\n\", -7, 32767);\n    printf(\"%u %x\\n\", 65535, 255);\n    printf(\"%c%c %s\\n\", 'O', 'K', \"ok\");\n    printf(\"[%5d][%3s][%2c]\\n\", 42, \"ab\", 'z');", "part": "04_library.md"},
  "putchar": {"kind": "function", "library": null, "forms": ["int putchar(int c)"], "desc": "Prints the one character whose code is c, at the print position, and returns c. The code 10 ('\\n') moves to the start of the next row.", "example": "int main(void)\n{\n    cls();\n    putchar('H');\n    putchar('i');\n    putchar('\\n');\n    putchar(65);\n    return putchar('!');", "part": "04_library.md"},
  "puts": {"kind": "function", "library": null, "forms": ["int puts(const char *s)"], "desc": "Prints the string s at the print position and then moves to the start of the next row. It returns 10, a non-negative number.", "example": "int main(void)\n{\n    int r;\n    cls();\n    puts(\"one\");\n    puts(\"two\");\n    r = puts(\"three\");\n    return r;", "part": "04_library.md"},
  "rand": {"kind": "function", "library": null, "forms": ["int rand(void)"], "desc": "The next number of a sequence of pseudo-random numbers, from 0 to 32767. The numbers come from a fixed sequence, so a program gives the same numbers on every run; srand starts the sequence at a place of your choice.", "example": "int main(void)\n{\n    int a, b, c;\n    a = rand();\n    b = rand();\n    c = rand();\n    cls();\n    printf(\"%d %d %d\", a, b, c);", "part": "04_library.md"},
  "register": {"kind": "keyword", "library": null, "forms": ["register declaration"], "desc": "A storage-class word for a local variable that suggests it be kept in a register. It is accepted and ignored: the variable is an ordinary local.", "example": "int main(void)\n{\n    register int i;\n    int sum = 0;\n    for (i = 1; i <= 4; i++)\n        sum += i;\n    return sum;\n}", "part": "03_keywords.md"},
  "return": {"kind": "keyword", "library": null, "forms": ["return;, return expression ;"], "desc": "Leaves the function at once. With an expression, it gives its value to the caller, converted to the function's type. A function of type void returns with return;, or by running off its closing brace.", "example": "int twice(int n)\n{\n    return n * 2;\n}\nvoid nothing(void)\n{\n    return;\n}", "part": "03_keywords.md"},
  "short": {"kind": "keyword", "library": null, "forms": ["short"], "desc": "The same as int: 16 bits, from -32768 to 32767. short int, signed short and unsigned short are accepted; unsigned short is unsigned.", "example": "int main(void)\n{\n    short s = 32767;\n    cls();\n    s = s + 1;\n    printf(\"%d\\n\", s);\n    return sizeof(short);\n}", "part": "03_keywords.md"},
  "signed": {"kind": "keyword", "library": null, "forms": ["signed"], "desc": "signed char is a one-byte number from -128 to 127: it is extended with its sign when used in an expression. signed alone, or signed int, is the same as int.", "example": "int main(void)\n{\n    signed char a = 128, b = 255;\n    unsigned char c = b;\n    cls();\n    printf(\"%d %d %d\\n\", a, b, c);\n    return 0;\n}", "part": "03_keywords.md"},
  "sound": {"kind": "function", "library": null, "forms": ["void sound(int reg, int value)"], "desc": "Writes value into register reg of the AY-3-8912 sound chip. The registers are numbered 0 to 15, as in the chip's data sheet: 0 to 5 are the tone periods of channels A, B and C, 6 the noise period, 7 the mixer, 8 to 10 the volumes, 11 to 13 the envelope. Use this for music on more than one channel, for noise and for envelopes; beep is simpler for a single note.", "example": "// ay: 0=254 1=0 7=62 8=0\nint main(void)\n{\n    sound(7, 0x3E);\n    sound(0, 254);\n    sound(1, 0);\n    sound(8, 15);\n    pause(30);", "part": "04_library.md"},
  "sprite_get": {"kind": "function", "library": null, "forms": ["void sprite_get(int row, int col, int w, int h, void *buf)"], "desc": "Copies a rectangle of the screen into memory: w cells wide and h cells high, whose top-left cell is at row and col. The buffer buf must hold w  h  9 bytes: for each cell, its 8 rows of pixels and then its attribute byte, the cells taken row by row. The sprite is a copy of the screen -- pixels and colours both.", "example": "// attr: 10 0 0x0A\n// attr: 20 30 0x0A\n// attr: 5 5 0x38\nchar buf[36];\nint main(void)\n{\n    cls();\n    ink(2);", "part": "04_library.md"},
  "sprite_put": {"kind": "function", "library": null, "forms": ["void sprite_put(int row, int col, int w, int h, void *buf)"], "desc": "Copies the rectangle of cells that sprite_get saved in buf back onto the screen, with its top-left cell at row and col: pixels and attributes, replacing what was there. The w and h must be the same as when it was saved. The example for sprite_get shows both.", "example": "", "part": "04_library.md"},
  "srand": {"kind": "function", "library": null, "forms": ["void srand(unsigned seed)"], "desc": "Restarts the sequence of rand at the place named by seed. The same seed always gives the same sequence.", "example": "int main(void)\n{\n    int a, b;\n    cls();\n    srand(1);\n    a = rand();\n    srand(0);\n    b = rand();", "part": "04_library.md"},
  "static": {"kind": "keyword", "library": null, "forms": ["static declaration"], "desc": "Inside a function, makes a variable that keeps its value between calls: it is made once, set to 0 or to its initialiser when the program starts, and never goes away. Outside any function, static makes a name private to the file; since a Leap-C program is one file, that changes nothing.", "example": "int count(void)\n{\n    static int n;\n    n++;\n    return n;\n}\nint main(void)\n{", "part": "03_keywords.md"},
  "strcat": {"kind": "function", "library": null, "forms": ["char strcat(char d, const char *s)"], "desc": "Appends the string s to the end of the string d (the NUL at the end of d is overwritten by the first character of s, and a NUL is put at the new end). Returns d.", "example": "char s[20];\nint main(void)\n{\n    cls();\n    strcpy(s, \"Leap\");\n    strcat(s, \"-C\");\n    puts(s);\n    return strlen(strcat(s, \"!\"));", "part": "04_library.md"},
  "strchr": {"kind": "function", "library": null, "forms": ["char strchr(const char s, int c)"], "desc": "Finds the first place in the string s where the character c occurs, and returns a pointer to it; or 0 (NULL) if it does not occur. c may be 0, in which case the result points to the NUL that ends s.", "example": "char s[20] = \"hello, world\";\nint main(void)\n{\n    char *p;\n    cls();\n    p = strchr(s, 'o');\n    printf(\"%s|%d\\n\", p, p - s);\n    printf(\"%d\", strchr(s, 'z') == 0);", "part": "04_library.md"},
  "strcmp": {"kind": "function", "library": null, "forms": ["int strcmp(const char a, const char b)"], "desc": "Compares the strings a and b character by character. The result is negative if a comes before b, positive if it comes after, and 0 if the strings are equal. The characters are compared as unsigned numbers (their codes, so \"Z\" comes before \"a\"), and a string that is a leading part of another comes before it.", "example": "int main(void)\n{\n    cls();\n    printf(\"%d %d %d %d\", strcmp(\"abc\", \"abd\") < 0,\n                          strcmp(\"abc\", \"abc\"),\n                          strcmp(\"b\", \"a\") > 0,\n                          strcmp(\"Z\", \"a\") < 0);\n    return strcmp(\"ab\", \"abc\") < 0;", "part": "04_library.md"},
  "strcpy": {"kind": "function", "library": null, "forms": ["char strcpy(char d, const char *s)"], "desc": "Copies the string s, with its NUL, to the memory at d, and returns d.", "example": "char d[10];\nint main(void)\n{\n    cls();\n    strcpy(d, \"copy\");\n    puts(d);\n    return strlen(strcpy(d, \"four\"));\n}", "part": "04_library.md"},
  "strlen": {"kind": "function", "library": null, "forms": ["unsigned strlen(const char *s)"], "desc": "The number of characters in the string s, not counting the NUL that ends it.", "example": "int main(void)\n{\n    cls();\n    printf(\"%u %u\", strlen(\"\"), strlen(\"Leap-C\"));\n    return strlen(\"0123456789\");\n}", "part": "04_library.md"},
  "strncpy": {"kind": "function", "library": null, "forms": ["char strncpy(char d, const char *s, unsigned n)"], "desc": "Copies at most n characters of the string s to d, and returns d. If s is shorter than n, the rest of the n bytes at d are filled with NULs.", "example": "int main(void)\n{\n    char d[6];\n    cls();\n    strncpy(d, \"abcdefgh\", 5);\n    d[5] = 0;\n    puts(d);\n    memset(d, '#', 5);", "part": "04_library.md"},
  "struct": {"kind": "keyword", "library": null, "forms": ["struct tag { member ; ... }, struct tag variable"], "desc": "Groups several named members into one object. The members follow one another in memory with no padding; the size is the sum of the sizes. A member may be of any type that is complete, including an array or another structure. A structure may hold a pointer to itself.", "example": "struct point { int x; int y; };\nvoid move(struct point *p, int dx)\n{\n    p->x += dx;\n}\nint main(void)\n{\n    struct point a;", "part": "03_keywords.md"},
  "switch": {"kind": "keyword", "library": null, "forms": ["switch ( expression ) { ... }"], "desc": "Chooses among several alternatives by the value of an integer or a char. The program jumps to the case label whose constant equals the value, or to default if none does, and carries on from there until a break.", "example": "void show(int c)\n{\n    switch (c) {\n    case 'a': case 'e': case 'i': case 'o': case 'u':\n        puts(\"vowel\");\n        break;\n    case ' ':\n        puts(\"space\");", "part": "03_keywords.md"},
  "tab": {"kind": "function", "library": null, "forms": ["void tab(int col)"], "desc": "Moves the print position to column col of the current row. The row is not changed.", "example": "int main(void)\n{\n    cls();\n    print(\"A\");\n    tab(10);\n    print(\"B\");\n    tab(35);\n    print(\"C\");", "part": "04_library.md"},
  "tape_load": {"kind": "function", "library": null, "forms": ["int tape_load(const char name, void addr, unsigned max)"], "desc": "Loads a data tape that tape_save wrote: it waits for the next data tape called name (the empty string \"\" accepts any name) and stores its bytes from the address addr, at most max of them. It returns the number of bytes loaded, or a negative number if it failed:", "example": "char buf[100];\nint main(void)\n{\n    int n;\n    cls();\n    print(\"Play the tape...\");\n    n = tape_load(\"mydata\", buf, 100);\n    if (n < 0) {", "part": "04_library.md"},
  "tape_save": {"kind": "function", "library": null, "forms": ["void tape_save(const char name, const void addr, unsigned len)"], "desc": "Writes len bytes, starting at the address addr, to the tape as a data tape called name. name is a string of 1 to 10 characters. The function returns when both blocks of the tape (a header and the data) have been sent: about 7 seconds, plus 5 to 7 milliseconds for every byte.", "example": "char data[8] = \"Leap-C\";\nint main(void)\n{\n    cls();\n    print(\"Record...\");\n    tape_save(\"mydata\", data, 7);\n    print(\"saved\");\n    return 0;", "part": "04_library.md"},
  "typedef": {"kind": "keyword", "library": null, "forms": ["typedef type name ;"], "desc": "Gives a new name to a type. After typedef unsigned word; the word word can be used wherever unsigned could. It works for any type: pointers, arrays, structures, pointers to functions.", "example": "typedef unsigned word;\ntypedef struct point { int x; int y; } Point;\nint main(void)\n{\n    Point p;\n    word w = 0;\n    p.x = 3;\n    p.y = 4;", "part": "03_keywords.md"},
  "unsigned": {"kind": "keyword", "library": null, "forms": ["unsigned"], "desc": "A whole number of 16 bits, from 0 to 65535. unsigned int and unsigned short are the same. unsigned char is a byte from 0 to 255, the same as char. It wraps around at both ends: 0 - 1 is 65535.", "example": "int main(void)\n{\n    unsigned u = 0;\n    cls();\n    u = u - 1;\n    printf(\"%u %u\\n\", u, u + 1);\n    printf(\"%d\\n\", u > 1);\n    return 0;", "part": "03_keywords.md"},
  "void": {"kind": "keyword", "library": null, "forms": ["void"], "desc": "Means \"nothing\". As a function's type, void f(void) is a function that returns no value; (void) in the parameter list says that it takes no arguments. A pointer to void, void *, can point at anything, and can be stored in, and taken from, any object pointer without a cast.", "example": "int x;\nvoid set(int v)\n{\n    x = v;\n}\nint main(void)\n{\n    void *v;", "part": "03_keywords.md"},
  "while": {"kind": "keyword", "library": null, "forms": ["while ( expression ) statement"], "desc": "Repeats the statement as long as the expression is not zero. The test is made before each time round, so the body may never run.", "example": "int main(void)\n{\n    int n = 1234, sum = 0;\n    while (n > 0) {\n        sum += n % 10;\n        n /= 10;\n    }\n    return sum;", "part": "03_keywords.md"},
};
